// pubspec.yaml:
//   hive: ^2.2.3
//   hive_flutter: ^1.1.0
// dev_dependencies:
//   hive_generator: ^2.0.1
//   build_runner: ^2.4.8

import 'package:hive_flutter/hive_flutter.dart';

// ────── Model with TypeAdapter (generated) ──────
part 'cart_item.g.dart';
@HiveType(typeId: 1)
class CartItem {
  @HiveField(0) final String sku;
  @HiveField(1) final int qty;
  @HiveField(2) final DateTime addedAt;
  const CartItem({required this.sku, required this.qty, required this.addedAt});
}

Future<void> initHive() async {
  await Hive.initFlutter();               // sets path
  Hive.registerAdapter(CartItemAdapter()); // from codegen
  await Hive.openBox<CartItem>('cart');
  await Hive.openBox('settings');          // untyped Box<dynamic>
}

// ────── Write / read ──────
final cart = Hive.box<CartItem>('cart');
await cart.put('SKU-42', CartItem(sku: 'SKU-42', qty: 2, addedAt: DateTime.now()));
final item = cart.get('SKU-42');

final settings = Hive.box('settings');
await settings.put('theme', 'dark');
final theme = settings.get('theme', defaultValue: 'system');

// ────── Reactive UI (no state-management framework required) ──────
ValueListenableBuilder(
  valueListenable: cart.listenable(),   // fires on any change
  builder: (_, Box<CartItem> box, __) => Text('${box.length} items'),
);
// Or a Stream:
cart.watch(key: 'SKU-42').listen((event) => print('sku changed to ${event.value}'));

// ────── Encrypted box (secret key derived from secure_storage) ──────
final keyBytes = await const FlutterSecureStorage().read(key: 'hive_key');
final cipher = HiveAesCipher(base64Decode(keyBytes!));
await Hive.openBox<CartItem>('cart_secure', encryptionCipher: cipher);

// Regen: dart run build_runner build --delete-conflicting-outputs
